#[test]
fn managed_windows_and_wsl_records_are_not_model_only_equivalent() {
    let mut windows = record("managed-model", BENCHMARK_TASKS[0], 100);
    windows.identity.model.backend_id = MANAGED_BACKEND_ID.to_owned();
    windows.identity.model.execution_environment =
        TelemetryValue::Measured("windows_native".to_owned());
    windows.identity.model.launch_policy_version =
        TelemetryValue::Measured("adr0155-managed-launch-v1".to_owned());
    let mut wsl = windows.clone();
    wsl.identity.model.execution_environment =
        TelemetryValue::Measured("wsl2_linux".to_owned());
    assert!(matches!(
        comparison_equivalence(&windows, &wsl),
        ComparisonEquivalence::NonEquivalent(differences)
            if differences.contains(&"execution_environment")
    ));
}

